        if (rp0 <= 0 || rp0 >= 1) continue;
        var rr = 6 + 130 * E.outCubic(rp0);
        ctx.globalAlpha = (1 - rp0) * 0.7; ctx.lineWidth = 1.4 / s; ctx.strokeStyle = 'rgba(255,120,100,1)';
